import json
from pathlib import Path
def rd(f):return json.loads(Path(f).read_text())
def save(f,v):Path(f).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
d=rd('source-walden.da.json');e=rd('source-walden.json')
for q in [d,e]:
 q['openingText']=rd('walden-modern-da.partial.json' if q is d else 'source-walden-modern-en.json')['chapters'][0]['paragraphs'][0]
d['about']='I to år og to måneder boede Henry David Thoreau i en hytte, han selv havde bygget ved Walden Pond nær Concord i Massachusetts. Han ville finde ud af, hvor lidt et menneske behøver for at leve godt. Han fører regnskab over søm og såbønner, måler søens dybde og ser naboerne slide for at få råd til ting, der efter hans mening koster dem deres frihed. Læg mærke til, hvor tit han taler direkte til dem, også når han er alene i skoven.\n\nWalden udkom i 1854, syv år efter at Thoreau var flyttet fra søen. Siden har mange forskellige læsere taget bogen til sig, fra modstandere af slaveriet til naturforkæmpere. Dens særlige tone ligger i springene mellem præcis iagttagelse, tør humor og spørgsmål om, hvordan man skal leve.'
angles=[
('Hvad koster friheden?','I kapitlet »Økonomi« opgør Thoreau hver udgift til hytten og hver cent, han tjener. Følg regnskabet. Hvad fortæller prisen på huset om den tid, han har til rådighed bagefter?','Jeg vil undersøge Thoreaus idé om, at en ting koster den del af mit liv, jeg må give for den.'),
('At se efter','Thoreau følger isen fra tilfrysning til tøbrud, lytter til ugler og lommer og tæller årringe. Hvad får han øje på, når han giver sig tid til at blive stående?','Jeg vil følge Thoreaus blik og undersøge, hvad evnen til at se efter har med et godt liv at gøre.'),
('Hvem lever mærkeligt?','Naboerne synes, Thoreau lever sært. Han synes, de går i søvne. Se, hvordan hans beskrivelser af deres to måder at leve på kan få læseren til at skifte side.','Jeg vil bruge forsøget ved søen til at overveje, hvad jeg selv regner for nødvendigt.'),
('At være alene','Thoreau har tit søen for sig selv. Han nyder stilheden, og han får gæster. Hvornår lyder det at være alene som et afsavn, og hvornår lyder det som en rigdom?','Jeg vil undersøge, hvad Thoreau finder i sit eget selskab, og om hans erfaring også gælder andre steder end ved søen.')]
for card,(title,t,o) in zip(d['angleCards'],angles):card.update(title=title,text=t,angleObjective=o)
cast=[('Henry David Thoreau','Manden bag forsøget','Thoreau er uddannet på Harvard og arbejder blandt andet som landmåler og blyantmager. Som 27-årig flytter han ud til Walden Pond. Han går tit ind til Concord og tager gerne imod gæster, men undrer sig over, hvor mange af hans naboer der tilsyneladende lever i stille fortvivlelse.'),('Walden Pond','Spejlet','En klar og dyb dødissø på knap 25 hektar i skoven ved Concord. Thoreau følger dens farver, dyreliv og temperatur gennem årstiderne. Den dybde og klarhed, han opsøger i sit eget liv, kan han også måle og se i søen.'),('Naboerne','Folk i Concord','Byens bønder og købmænd arbejder hårdt, gældsætter sig og køber mere. Thoreau skriver med både varme og bid om dem. Han spørger, hvornår arbejdet for at leve kom til at fylde hele livet.'),('Hytten','Et hus til 28 dollar og 12½ cent','Thoreau bygger hytten med ét rum på Emersons jord. Han opgiver priserne på alt fra gamle vinduer til dørklinken. Læseren kan selv regne efter, hvor meget det kostede ham at få tag over hovedet.'),('Ralph Waldo Emerson','Vennen i baggrunden','Forfatteren Ralph Waldo Emerson er Thoreaus ven og ejer grunden ved søen. Hans tanker om at stole på sin egen dømmekraft hører til bogens baggrund.')]
for card,(n,r,t) in zip(d['cast'],cast):card.update(name=n,role=r,description=t)
why=[('At lægge mærke til naturen','Walden har sat spor i amerikansk naturskrivning. Når Thoreau følger en lom ned under vandet eller venter på, at isen bryder op, giver han dyret og søen en plads i bogen, uanset hvad mennesker kan bruge dem til.'),('En pris målt i levetid','Hvad koster et hus, hvis man regner i år af sit liv? I kapitlet »Økonomi« sætter Thoreau priserne på materialer op imod de arbejdsdage, det kræver at betale dem. Spørgsmålet gælder også læserens egne valg.'),('At vælge sit liv','Thoreau fortæller, at han gik ud i skoven for at leve bevidst. Han opfordrer læseren til selv at undersøge sine behov. Hvilke valg har man truffet, og hvilke vaner har man bare overtaget?')]
for card,(t,b) in zip(d['whyItMatters'],why):card.update(title=t,body=b)
e['about']='Walden recounts the two years and two months Henry David Thoreau spent living in a cabin he built beside Walden Pond near Concord, Massachusetts. He wanted to learn how little a person needed to live well. He keeps accounts for nails and seed beans, measures the pond’s depth, and watches his neighbors work for things he believes cost them their freedom. Notice how often he addresses those neighbors, even from the woods.\n\nPublished in 1854, seven years after Thoreau left the pond, Walden found readers among opponents of slavery and later among conservationists. Its distinctive voice moves between close observation, deadpan humor, and questions about how to live.'
e['cast'][4]['description']='Thoreau’s friend and mentor, Emerson owned the land on which the cabin stood. His writing on self-reliance helps explain the intellectual background of the experiment.'
e['whyItMatters'][0].update(title='Paying Attention to Nature',body='Walden helped shape American nature writing. In tracking a loon underwater or waiting for the ice to break, Thoreau makes room for the animal and the pond regardless of what people can use them for.')
e['whyItMatters'][1]['body']='What does a house cost in years of life? In “Economy,” Thoreau weighs his building expenses against the days of labor needed to pay for them. His question also applies to the reader’s own choices.'
e['whyItMatters'][2]['body']='Thoreau says he went to the woods because he wished to live deliberately. He asks readers to examine their needs for themselves. Which choices have they made, and which habits have they simply inherited?'
save('walden.da.json',d);save('walden.json',e)
